CREATE TABLE `ab_affiliates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `name` varchar(255) NOT NULL,
  `companyName` varchar(255) NOT NULL,
  `type` int(11) NOT NULL DEFAULT '0',
  `defaultPromoCode` varchar(255) NOT NULL,
  `siteid` int(11) NOT NULL,
  `isEnabled` int(11) NOT NULL DEFAULT '0',
  `bookingReferenceFormat` varchar(30) NOT NULL DEFAULT '{S}{R}{P}{I}',
  `bookingReferencePrefix` varchar(5) NOT NULL DEFAULT 'W',
  `bookingSequenceName` varchar(80) NOT NULL DEFAULT 'bookings',
  `paymentPropertiesNode` varchar(50) DEFAULT NULL,
  `bookingFee` decimal(13,2) NOT NULL DEFAULT '0.00',
  `bookingFeeType` smallint(6) NOT NULL DEFAULT '1',
  `refundBookingFeeOnCancellation` int(1) NOT NULL DEFAULT '0',
  `debitCardFee` decimal(13,2) NOT NULL DEFAULT '0.00',
  `debitCardFeeType` smallint(6) NOT NULL DEFAULT '0',
  `creditCardFee` decimal(13,2) NOT NULL DEFAULT '0.00',
  `creditCardFeeType` smallint(6) NOT NULL DEFAULT '0',
  `paypalFee` decimal(13,2) NOT NULL DEFAULT '0.00',
  `paypalUsePercent` int(1) NOT NULL DEFAULT '0',
  `refundCardFeeOnCancellation` int(1) NOT NULL DEFAULT '0',
  `cancellationCharge` decimal(13,2) NOT NULL DEFAULT '0.00',
  `cancellationChargeType` smallint(6) NOT NULL DEFAULT '1',
  `amendCancel_minHoursBeforeDateOfArrival` int(11) NOT NULL DEFAULT '0',
  `amendCancel_ignoreTimeOfDay` smallint(6) NOT NULL DEFAULT '0',
  `bookingDateType` smallint(6) NOT NULL DEFAULT '1',
  `vatRate` decimal(13,2) NOT NULL,
  `vatNo` varchar(50) NOT NULL,
  `vatAddress` varchar(255) NOT NULL,
  `vatCompany` varchar(255) NOT NULL,
  `stateTaxRate` decimal(13,2) NOT NULL DEFAULT '0.00',
  `cityTax` decimal(13,2) DEFAULT '0.00',
  `smsAssistancePrice` decimal(13,2) NOT NULL DEFAULT '-1.00',
  `crmType` int(11) NOT NULL DEFAULT '0',
  `enable3DSecure` smallint(6) NOT NULL DEFAULT '0',
  `secure3DPurchaseDesc` varchar(80) DEFAULT NULL,
  `secure3DWebsiteUrl` varchar(255) DEFAULT NULL,
  `callCentreNumber` varchar(50) NOT NULL,
  `isUserAccountsEnabled` int(11) NOT NULL DEFAULT '0',
  `isSaveForLaterEnabled` int(11) NOT NULL DEFAULT '0',
  `isSaveForLaterReminderEnabled` int(11) NOT NULL DEFAULT '0',
  `isSocialLoginEnabled` int(1) NOT NULL DEFAULT '0',
  `isDataCashEnabled` int(11) NOT NULL DEFAULT '0',
  `isPaypalEnabled` int(1) NOT NULL DEFAULT '0',
  `isNetaxeptEnabled` int(11) NOT NULL DEFAULT '0',
  `isStripePaymentEnabled` int(11) NOT NULL DEFAULT '0',
  `isMainAffiliate` int(11) NOT NULL DEFAULT '0',
  `cardPaymentsEnabled` int(11) NOT NULL DEFAULT '0',
  `payPalEnabled` int(1) NOT NULL DEFAULT '0',
  `isArchived` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code_UNIQUE` (`code`),
  KEY `siteid` (`siteid`),
  KEY `fk_affils_bookingSequenceName_idx` (`bookingSequenceName`),
  KEY `idx_affils_code` (`code`),
  CONSTRAINT `fk_affils_siteId` FOREIGN KEY (`siteid`) REFERENCES `ab_sites` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=559 DEFAULT CHARSET=utf8;
