CREATE TABLE `payments_custom_fields` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `field` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_UNIQUE` (`id`),
  KEY `idx_paycustval_field` (`field`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8;

CREATE TABLE `partial_payments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_id` varchar(255) NOT NULL,
  `type` int(11) NOT NULL,
  `reference` varchar(255) NOT NULL,
  `amount` varchar(255) NOT NULL DEFAULT '0.00',
  `amount_refunded` varchar(255) NOT NULL DEFAULT '0.00',
  `created` datetime DEFAULT CURRENT_TIMESTAMP,
  `migration` int(1) NOT NULL DEFAULT '0',
  `carpark_id` int(11) DEFAULT NULL,
  `parent_payment` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_UNIQUE` (`id`),
  KEY `fk_partial_payment_payment_gateway_type_payment_type_idx` (`type`),
  KEY `fk_partial_payment_ab_carparks_carParkId_idx` (`carpark_id`),
  KEY `fk_partial_payment_payment_parentPayment_idx` (`parent_payment`),
  CONSTRAINT `fk_partial_payment_payment_gateway_type_type` FOREIGN KEY (`type`) REFERENCES `payment_gateway_types` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_partial_payment_ab_carparks_carParkId` FOREIGN KEY (`carpark_id`) REFERENCES `ab_carparks` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_partial_payment_payment_parentPayment` FOREIGN KEY (`parent_payment`) REFERENCES `payments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

INSERT INTO `partial_payments` (`id`, `transaction_id`, `type`, `reference`, `amount`, `parent_payment`) VALUES (1, 'txID', 1, 'ref', '10.00', 1);

-- kmp_advancebooker.payments_custom_values definition

CREATE TABLE `payments_custom_values` (
  `id` int NOT NULL AUTO_INCREMENT,
  `field` int DEFAULT NULL,
  `value` varchar(255) NOT NULL,
  `paymentId` int NOT NULL,
  `partialPaymentId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_UNIQUE` (`id`),
  UNIQUE KEY `field_paymentId_UNIQUE` (`paymentId`,`partialPaymentId`,`field`),
  KEY `fk_payCustVal_field_idx` (`field`),
  KEY `fk_payCustVal_payId_idx` (`paymentId`),
  CONSTRAINT `fk_payCustVal_field` FOREIGN KEY (`field`) REFERENCES `payments_custom_fields` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_payCustVal_payId` FOREIGN KEY (`paymentId`) REFERENCES `payments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

CREATE TABLE `refunds` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `paymentId` int(11) NOT NULL,
  `type` int(11) NOT NULL,
  `reference` varchar(255) NOT NULL,
  `amount` varchar(255) NOT NULL,
  `notes` longtext,
  `created` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_UNIQUE` (`id`),
  KEY `fk_refunds_payId_idx` (`paymentId`),
  KEY `fk_refunds_type_idx` (`type`),
  CONSTRAINT `fk_refunds_payId` FOREIGN KEY (`paymentId`) REFERENCES `payments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_refunds_type` FOREIGN KEY (`type`) REFERENCES `payment_gateway_types` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1864 DEFAULT CHARSET=utf8;

CREATE ALGORITHM=UNDEFINED
SQL SECURITY DEFINER 
VIEW `selected_payment_gateway`
AS select `pg`.`affiliateId` AS `affiliateId`,NULL AS `carParkId`,`pg`.`type` AS `type`,`pg`.`credentialsJson` AS `credentialsJson`,`pg`.`id` AS `gatewayId`,'AFFILIATE' AS `gatewayType` from `payment_gateways` `pg` union all select NULL AS `NULL`,`pgcp`.`carParkId` AS `carParkId`,`pgcp`.`type` AS `type`,`pgcp`.`credentialsJson` AS `credentialsJson`,`pgcp`.`id` AS `gatewayId`,'CARPARK' AS `CARPARK` from (`payment_gateways_car_park` `pgcp` join `ab_carparks` `abcp` on((`pgcp`.`carParkId` = `abcp`.`id`))) where (`abcp`.`isCarParkPaymentEnabled` = 1);

ALTER TABLE `ab_sites` 
ADD CONSTRAINT `fk_sitesa_defaultAffiliateId`
  FOREIGN KEY (`defaultAffiliateId`)
  REFERENCES `ab_affiliates` (`id`)
  ON DELETE CASCADE
  ON UPDATE CASCADE; 
  
