--
-- Table structure for table `ab_contacts`
--

DROP TABLE IF EXISTS `ab_contacts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ab_contacts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `registered` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified` datetime NOT NULL,
  `password` varchar(100) DEFAULT NULL,
  `failedLogins` int(11) NOT NULL DEFAULT '0',
  `emailAddress` varchar(255) NOT NULL,
  `profileImageUrl` varchar(450) DEFAULT NULL,
  `title` varchar(10) DEFAULT NULL,
  `firstName` varchar(255) DEFAULT NULL,
  `lastName` varchar(255) DEFAULT NULL,
  `telNo` varchar(50) DEFAULT NULL,
  `mobileNo` varchar(50) DEFAULT NULL,
  `faxNo` varchar(50) DEFAULT NULL,
  `occupation` varchar(255) DEFAULT NULL,
  `company` varchar(255) DEFAULT NULL,
  `department` varchar(255) DEFAULT NULL,
  `abtaNo` varchar(100) DEFAULT NULL,
  `address1` varchar(255) DEFAULT NULL,
  `address2` varchar(255) DEFAULT NULL,
  `town` varchar(255) DEFAULT NULL,
  `county` varchar(255) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `postcode` varchar(50) DEFAULT NULL,
  `historicId` int(11) DEFAULT NULL,
  `siteId` int(11) DEFAULT '1',
  `activated` int(1) DEFAULT NULL,
  `languageId` int(4) DEFAULT '1',
  `tcsOptIn` int(1) NOT NULL DEFAULT '0',
  `emailOptIn` int(1) NOT NULL DEFAULT '0',
  `smsOptIn` int(1) NOT NULL DEFAULT '0',
  `parkingOptIn` int(1) NOT NULL DEFAULT '0',
  `marketingOptIn` datetime DEFAULT NULL,
  `transactionalOptOut` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_contacts_siteId_idx` (`siteId`),
  KEY `fk_contacts_languageId_idx` (`languageId`),
  KEY `idx_contacts_emailaddress` (`emailAddress`),
  CONSTRAINT `fk_contacts_languageId` FOREIGN KEY (`languageId`) REFERENCES `languages` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_contacts_siteId` FOREIGN KEY (`siteId`) REFERENCES `ab_sites` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51210 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ab_contacts`
--

LOCK TABLES `ab_contacts` WRITE;
/*!40000 ALTER TABLE `ab_contacts` DISABLE KEYS */;
