  INDEX `fk_partial_payment_amount_partial_payments_partial_payment__idx` (`partial_payment_id` ASC),
  INDEX `fk_partial_payment_amount_refunds_refund_id_idx` (`refund_id` ASC),
  CONSTRAINT `fk_partial_payment_amount_partial_payments_partial_payment_id`
    FOREIGN KEY (`partial_payment_id`)
    REFERENCES `partial_payments` (`id`)
    ON DELETE CASCADE
    ON UPDATE CASCADE,
  CONSTRAINT `fk_partial_payment_amount_refunds_refund_id`
    FOREIGN KEY (`refund_id`)
    REFERENCES `refunds` (`id`)
    ON DELETE CASCADE
    ON UPDATE CASCADE);
    
